import{_ as e}from"./chunks/img.Dck1PxLc.js";import{_ as n,c as i,o as r,a0 as a}from"./chunks/framework.DKRgXLPU.js";const t=JSON.parse('{"title":"Über die Pétanque-Akademie","description":"","frontmatter":{},"headers":[],"relativePath":"de/about.md","filePath":"de/about.md"}');const s=n({name:"de/about.md"},[["render",function(n,t,s,l,h,o){return r(),i("div",null,[...t[0]||(t[0]=[a('<h1 id="uber-die-petanque-akademie" tabindex="-1">Über die Pétanque-Akademie <a class="header-anchor" href="#uber-die-petanque-akademie" aria-label="Permalink to &quot;Über die Pétanque-Akademie&quot;">​</a></h1><h2 id="eine-leidenschaft-fur-petanque" tabindex="-1">Eine Leidenschaft für Pétanque <a class="header-anchor" href="#eine-leidenschaft-fur-petanque" aria-label="Permalink to &quot;Eine Leidenschaft für Pétanque&quot;">​</a></h2><p>Willkommen an der Pétanque-Akademie, wo die tiefe Leidenschaft für Pétanque seit über 45 Jahren die treibende Kraft ist. Meine Reise mit diesem Sport war geprägt von Hingabe, Können und ungebrochener Begeisterung.</p><p>Pétanque ist mehr als nur ein Spiel; es ist eine Möglichkeit, Kontakte zu knüpfen, Strategien zu entwickeln und die Natur zu genießen, und ich hatte das Glück, seine vielen Facetten fast ein halbes Jahrhundert lang zu erleben. Ob es nun das präzise Platzieren einer Boule-Kugel oder die Kameradschaft auf dem Spielfeld ist – meine Leidenschaft für Pétanque ist ungebrochen.</p><p><img src="'+e+'" alt="Patrik Wiik with friends"></p><p><em>Das Teilen dieser Leidenschaft mit Freunden macht Pétanque so besonders. Die unzähligen Stunden auf dem Spielfeld, erfüllt von Lachen, freundschaftlichem Wettkampf und gemeinsamen Geschichten, schaffen Freundschaften, die ein Leben lang halten.</em></p><hr><h2 id="meine-mission" tabindex="-1">Meine Mission <a class="header-anchor" href="#meine-mission" aria-label="Permalink to &quot;Meine Mission&quot;">​</a></h2><p>Die Mission der Pétanque Academy besteht darin, Spitzenspielern zu helfen, ihr volles Potenzial auszuschöpfen, indem sie sich mit dem mentalen Spiel auseinandersetzt – dem oft übersehenen Aspekt, der gute Spieler von großartigen Spielern unterscheidet.</p><p>Über diese Website teile ich:</p><ul><li><strong>Mentale Spielmodelle</strong>, entwickelt aus jahrzehntelanger Erfahrung</li><li><strong>Praktische Werkzeuge und Vorlagen</strong> für die Zielsetzung und das Training</li><li><strong>Workshop-Methoden</strong> zur Schaffung psychologischer Sicherheit</li><li><strong>Evidenzbasierte Ansätze</strong> zur Leistungssteigerung unter Druck</li></ul><p>Hier geht es nicht um technisches Coaching, sondern darum, die mentale Grundlage zu schaffen, die es Ihnen ermöglicht, Ihre technischen Fähigkeiten dann zum Vorschein zu bringen, wenn es am wichtigsten ist.</p><hr><h2 id="warum-ich-diese-website-erstellt-habe" tabindex="-1">Warum ich diese Website erstellt habe <a class="header-anchor" href="#warum-ich-diese-website-erstellt-habe" aria-label="Permalink to &quot;Warum ich diese Website erstellt habe&quot;">​</a></h2><p>Nach über 45 Jahren im Pétanque habe ich unzählige talentierte Spieler gesehen, die nicht mit der Technik, sondern mit Folgendem zu kämpfen hatten:</p><ul><li><strong>Der innere Kritiker</strong>, der nach Fehlern das Selbstvertrauen zerstört</li><li><strong>Druck</strong>, der sie dazu bringt, im Wettkampf anders zu spielen.</li><li><strong>Mangelnde Struktur</strong> im mentalen Training</li><li><strong>Isolation</strong> auf ihrem Entwicklungsweg</li></ul><p>Diese Website soll das ändern. Alle Inhalte hier sind so gestaltet, dass sie sofort praktisch anwendbar sind – Vorlagen zum Kopieren, Frameworks, die Sie noch heute einsetzen können, und Tools, die sich im realen Wettbewerb bewähren.</p><hr><h2 id="nehmen-sie-kontakt-auf" tabindex="-1">Nehmen Sie Kontakt auf <a class="header-anchor" href="#nehmen-sie-kontakt-auf" aria-label="Permalink to &quot;Nehmen Sie Kontakt auf&quot;">​</a></h2><p>Ich freue mich, von Ihnen zu hören! Ob Sie Fragen haben, Ihre Erfahrungen teilen möchten oder an Workshops und Schulungen interessiert sind, melden Sie sich gerne.</p><h3 id="kontaktinformationen" tabindex="-1">Kontaktinformationen <a class="header-anchor" href="#kontaktinformationen" aria-label="Permalink to &quot;Kontaktinformationen&quot;">​</a></h3><p><strong>E-Mail:</strong> <a href="mailto:patrik.wiik@gmail.com" target="_blank" rel="noreferrer">patrik.wiik@gmail.com</a></p><p><strong>Facebook:</strong> <a href="https://www.facebook.com/patrik.wiik" target="_blank" rel="noreferrer">facebook.com/patrik.wiik</a></p><hr><h2 id="helfen-sie-mir-diese-website-zu-verbessern" tabindex="-1">Helfen Sie mir, diese Website zu verbessern <a class="header-anchor" href="#helfen-sie-mir-diese-website-zu-verbessern" aria-label="Permalink to &quot;Helfen Sie mir, diese Website zu verbessern&quot;">​</a></h2><p>Ihr Feedback ist unschätzbar wertvoll! Diese Seite wird ständig weiterentwickelt, basierend auf den tatsächlichen Bedürfnissen von Spitzenspielern.</p><h3 id="ich-wurde-mich-freuen-von-ihnen-zu-horen-uber" tabindex="-1">Ich würde mich freuen, von Ihnen zu hören über: <a class="header-anchor" href="#ich-wurde-mich-freuen-von-ihnen-zu-horen-uber" aria-label="Permalink to &quot;Ich würde mich freuen, von Ihnen zu hören über:&quot;">​</a></h3><div class="tip custom-block"><p class="custom-block-title">Was würde Ihnen am meisten helfen?</p><ul><li><p><strong>Welche Inhalte würden Sie gerne häufiger sehen?</strong></p><ul><li>Weitere Techniken für mentale Spiele?</li><li>Mehr praktische Vorlagen?</li><li>Fallstudien von Spitzenspielern?</li></ul></li><li><p><strong>Was fehlt auf der Website?</strong></p><ul><li>Welche Themen wurden nicht behandelt?</li><li>Tools, von denen ihr euch wünscht, dass es sie gäbe?</li><li>Ressourcen, die Sie nicht finden können?</li></ul></li><li><p><strong>Was funktioniert gut?</strong> Welche Seiten waren am hilfreichsten? Welche Werkzeuge haben Sie tatsächlich verwendet?</p><ul><li>Was hat für Sie den größten Unterschied gemacht?</li></ul></li><li><p><strong>Wie kann ich es verbessern?</strong></p><ul><li>Verbesserungen der Navigation?</li><li>Inhaltsorganisation?</li><li>Weitere Beispiele?</li><li>Unterschiedliche Formate?</li></ul></li></ul></div><h3 id="senden-sie-mir-ihr-feedback" tabindex="-1">Senden Sie mir Ihr Feedback <a class="header-anchor" href="#senden-sie-mir-ihr-feedback" aria-label="Permalink to &quot;Senden Sie mir Ihr Feedback&quot;">​</a></h3><p><strong>Senden Sie Ihre Gedanken per E-Mail an:</strong> <a href="mailto:patrik.wiik@gmail.com" target="_blank" rel="noreferrer">patrik.wiik@gmail.com</a></p><p><strong>Vorschläge für die Betreffzeile:</strong></p><ul><li>&quot;Feedback zur Website: [Ihr Thema]&quot;</li><li>&quot;Inhaltsanfrage: [Was Sie benötigen]&quot;</li><li>&quot;Erfolgsgeschichte: [Wie es geholfen hat]&quot;</li><li>&quot;Vorschlag: [Ihre Idee]&quot;</li></ul><p><strong>Was sollte enthalten sein:</strong></p><ul><li>Ihr aktuelles Niveau/Ihre Erfahrung</li><li>Woran Sie arbeiten</li><li>Konkretes Feedback oder Anfragen Gibt es Erfolgsgeschichten, die den Inhalt genutzt haben?</li></ul><hr><h2 id="was-andere-sagen" tabindex="-1">Was andere sagen <a class="header-anchor" href="#was-andere-sagen" aria-label="Permalink to &quot;Was andere sagen&quot;">​</a></h2><details class="details custom-block"><summary>Feedback von Elite-Spielern</summary><p><em>„Die Inhalte zum Thema mentales Training haben meine Herangehensweise an Wettkämpfe komplett verändert. Allein das Inner Coach-Konzept war es wert, diese Website zu finden.“</em> — Regionalmeister, Frankreich</p><p><em>„Endlich jemand, der versteht, dass die Technik nicht das Problem ist. Die Workshop-Methodik hat unserem Verein eine völlig neue Trainingsmethode eröffnet.“</em> — Nationalspieler, Schweden</p><p><em>„Die Ziel- und Tagebuchvorlage sind genau das, was ich brauchte. Simpel, praktisch und tatsächlich nutzbar.“</em> — Turnierspieler, Spanien</p></details><hr><h2 id="uber-den-inhalt" tabindex="-1">Über den Inhalt <a class="header-anchor" href="#uber-den-inhalt" aria-label="Permalink to &quot;Über den Inhalt&quot;">​</a></h2><p>Alle Inhalte auf dieser Website sind:</p><ul><li><strong>Kostenlos und zugänglich</strong> - Keine Bezahlschranken, keine versteckten Inhalte</li><li><strong>Praktisch und umsetzbar</strong> - Vorlagen, die Sie noch heute verwenden können</li><li><strong>Evidenzbasiert</strong> - Basierend auf psychologischer Forschung und über 45 Jahren Erfahrung</li><li><strong>Ständig aktualisiert</strong> - Neue Inhalte werden basierend auf Ihrem Feedback hinzugefügt</li></ul><hr><h2 id="datenschutz-amp-cookies" tabindex="-1">Datenschutz &amp; Cookies <a class="header-anchor" href="#datenschutz-amp-cookies" aria-label="Permalink to &quot;Datenschutz &amp;amp; Cookies&quot;">​</a></h2><p>Diese Website nutzt Google AdSense, um ihren Betrieb zu finanzieren. Durch die Nutzung dieser Website erklären Sie sich mit der Verwendung von Cookies durch Google zur Personalisierung von Werbung und zu Analysezwecken einverstanden.</p><p><strong>Wir respektieren Ihre Privatsphäre:</strong> Es werden keine personenbezogenen Daten über die Standardanalyse hinaus erhoben. Keine E-Mail-Listen oder Spam Die Kontaktinformationen werden ausschließlich zur Beantwortung Ihrer Nachrichten verwendet.</p><hr><h2 id="verbinden-amp-teilen" tabindex="-1">Verbinden &amp; Teilen <a class="header-anchor" href="#verbinden-amp-teilen" aria-label="Permalink to &quot;Verbinden &amp;amp; Teilen&quot;">​</a></h2><p>Wenn Sie diesen Inhalt wertvoll finden:</p><ul><li><strong>Teile es</strong> mit deinen Trainingspartnern</li><li><strong>Empfehlen Sie es Ihrem Verein</strong></li><li><strong>Verlinken Sie es</strong> aus Ihren eigenen Ressourcen</li><li><strong>Geben Sie Feedback,</strong> um die Verbesserung zu unterstützen.</li></ul><p>Gemeinsam können wir das mentale Niveau des Boule-Spiels weltweit steigern.</p><hr><p>Vielen Dank, dass Sie Teil der Pétanque-Akademie sind!</p><p><em>— Patrik Wiik</em></p>',53)])])}]]);export{t as __pageData,s as default};
